<template><view class="page"><AppHeader/><view class="content"><view class="search">⌕ <input placeholder="搜索目的地 / 旅行主题"/></view><scroll-view scroll-x class="filter"><view v-for="(f,i) in filters" :key="f" class="filter-item" :class="{on:i===0}">{{f}}⌄</view></scroll-view>
<view class="smart" @click="go('/pages/custom/params')"><view><view class="tag">AI 智能匹配</view><view class="smart-title">一键生成专属路线</view><view class="sub">30 秒匹配你的积分预算与偏好</view></view><view class="smart-go">→</view></view>
<view class="title-row"><view class="section-title">为你推荐</view><text class="sub">仅展示已上架路线</text></view><view v-if="routes.length" class="waterfall"><view class="route-card" v-for="(r,i) in routes" :key="r.id||r.name" @click="openRoute(r)"><view class="route-img" :style="{height:(i%2?260:330)+'rpx'}"><image :src="r.img" mode="aspectFill"/><view class="fav" :class="{on:favorites.has(r.name)}" @click.stop="toggleFavorite(r)">{{favorites.has(r.name)?'♥':'♡'}}</view></view><view class="route-body"><view class="route-name">{{r.name}}</view><view><text class="tag">{{r.days}}</text><text class="tag tag-orange">{{r.points}}</text></view><view class="sub">{{r.theme}}</view><view class="target" :class="{on:targets.has(r.name)}" @click.stop="toggleTarget(r)">{{targets.has(r.name)?'✓ 已加入上岸心愿':'＋ 设为上岸目标'}}</view></view></view></view><view v-else class="empty-routes"><view>🧭</view><b>路线正在更新中</b><text>当前暂无已上架路线，稍后再来看看吧</text></view>
<view class="section-title">上岸学长旅行种草</view><view class="video-card"><image src="https://images.unsplash.com/photo-1527631746610-bca00a040d60?w=900" mode="aspectFill"/><view class="play">▶</view><view class="video-txt">考研结束后的第一站，去看山河辽阔</view></view></view><BottomNav active="旅行"/></view></template>
<script setup>
import{onMounted,onUnmounted,ref}from'vue';import{onShow,onHide,onPullDownRefresh}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import BottomNav from'../../components/BottomNav.vue';import{getPublicRoutes,trackPreference}from'../../utils/api.js'
const filters=['目的地','主题','天数','积分'];const routes=ref([]);const favorites=ref(new Set(uni.getStorageSync('favoriteRoutes')||[]));const targets=ref(new Set(uni.getStorageSync('targetRoutes')||[]));
let refreshTimer=null;const loadRoutes=async(showError=false)=>{const remote=await getPublicRoutes();routes.value=remote.filter(r=>r.status!==false).map(r=>({id:r.id,name:r.name,days:r.days,points:`${Number(r.price)} 积分`,theme:`${r.category} · ${r.agency}`,img:r.image}));if(showError&&remote.__fromCache)uni.showToast({title:'后端连接失败，当前显示缓存数据',icon:'none'})};const startAutoRefresh=()=>{clearInterval(refreshTimer);loadRoutes();refreshTimer=setInterval(()=>loadRoutes(),3000)};const stopAutoRefresh=()=>{clearInterval(refreshTimer);refreshTimer=null};onMounted(startAutoRefresh);onShow(startAutoRefresh);onHide(stopAutoRefresh);onUnmounted(stopAutoRefresh);onPullDownRefresh(async()=>{await loadRoutes(true);uni.stopPullDownRefresh()})
const persist=(key,setRef)=>uni.setStorageSync(key,[...setRef.value]);const toggleFavorite=r=>{const next=new Set(favorites.value);const adding=!next.has(r.name);adding?next.add(r.name):next.delete(r.name);favorites.value=next;persist('favoriteRoutes',favorites);trackPreference({type:'route',key:r.id||r.name,name:r.name,action:adding?'favorite_add':'favorite_remove',score:adding?3:-3});uni.showToast({title:adding?'已收藏这段旅程':'已取消收藏',icon:'none'})};const toggleTarget=r=>{const next=new Set(targets.value);const adding=!next.has(r.name);adding?next.add(r.name):next.delete(r.name);targets.value=next;persist('targetRoutes',targets);trackPreference({type:'route',key:r.id||r.name,name:r.name,action:adding?'target_add':'target_remove',score:adding?5:-5});uni.showToast({title:adding?'已加入上岸心愿':'已移出上岸心愿',icon:'none'})};const openRoute=r=>{trackPreference({type:'route',key:r.id||r.name,name:r.name,action:'view',score:1});go('/pages/custom/detail')};const go=url=>uni.navigateTo({url})
</script>
<style scoped>.search{height:86rpx;background:#fff;border-radius:24rpx;display:flex;align-items:center;padding:0 24rpx;font-size:40rpx;color:#8a9694}.search input{font-size:26rpx;flex:1;margin-left:14rpx}.filter{white-space:nowrap;margin:22rpx 0}.filter-item{display:inline-block;padding:16rpx 28rpx;background:#fff;border-radius:99rpx;margin-right:14rpx}.filter-item.on{background:#172c2a;color:white}.smart{display:flex;align-items:center;justify-content:space-between;padding:30rpx;background:linear-gradient(135deg,#dff5ef,#f1fbf8);border-radius:28rpx}.smart-title{font-size:36rpx;font-weight:900;margin:4rpx 0 8rpx}.smart-go{width:70rpx;height:70rpx;border-radius:50%;background:#12a594;color:#fff;text-align:center;line-height:66rpx;font-size:42rpx}.waterfall{columns:2;column-gap:18rpx}.route-card{break-inside:avoid;background:#fff;border-radius:25rpx;overflow:hidden;margin-bottom:18rpx}.route-img{position:relative}.route-img image{width:100%;height:100%}.fav{position:absolute;right:14rpx;top:14rpx;width:58rpx;height:58rpx;border-radius:50%;background:rgba(255,255,255,.92);text-align:center;line-height:55rpx;font-size:38rpx;color:#52615e;transition:.2s}.fav.on{color:#f04452;background:#fff0f1;transform:scale(1.08)}.route-body{padding:18rpx}.route-name{font-size:28rpx;font-weight:850;margin-bottom:14rpx}.target{color:#ff7a35;font-size:22rpx;margin-top:15rpx;font-weight:700}.target.on{display:inline-flex;background:#e7f6f2;color:#078b7b;padding:9rpx 14rpx;border-radius:99rpx}.empty-routes{text-align:center;background:#fff;padding:80rpx 20rpx;border-radius:28rpx}.empty-routes view{font-size:70rpx}.empty-routes b,.empty-routes text{display:block;margin-top:15rpx}.empty-routes text{font-size:23rpx;color:#778684}.video-card{height:360rpx;border-radius:28rpx;overflow:hidden;position:relative}.video-card image{width:100%;height:100%}.play{position:absolute;left:50%;top:45%;transform:translate(-50%,-50%);width:82rpx;height:82rpx;border-radius:50%;background:rgba(255,255,255,.9);color:#ff7a35;text-align:center;line-height:82rpx}.video-txt{position:absolute;left:24rpx;bottom:24rpx;color:#fff;font-weight:800}</style>
